class Solution {
    private final Random rng = new Random(7);
    private int[] a;

    public int[] sortScores(int[] scores) {
        a = scores.clone();
        sort(0, a.length - 1);
        return a;
    }

    private void swap(int i, int j) { int t = a[i]; a[i] = a[j]; a[j] = t; }

    private void sort(int lo, int hi) {
        if (lo >= hi) return;
        swap(lo + rng.nextInt(hi - lo + 1), hi);
        int p = a[hi], i = lo;
        for (int j = lo; j < hi; j++) if (a[j] < p) swap(i++, j);
        swap(i, hi);
        sort(lo, i - 1);
        sort(i + 1, hi);
    }
}

