        swap(a[lo + rng() % (hi - lo + 1)], a[hi]);
        int p = a[hi], i = lo;
        for (int j = lo; j < hi; j++) if (a[j] < p) swap(a[i++], a[j]);
        swap(a[i], a[hi]);
        sort(lo, i - 1);
        sort(i + 1, hi);
    }

