static void quick(int* a, int lo, int hi) {
    if (lo >= hi) return;
    swap(a, lo + rand() % (hi - lo + 1), hi);
    int p = a[hi], i = lo;
    for (int j = lo; j < hi; j++) if (a[j] < p) swap(a, i++, j);
    swap(a, i, hi);
    quick(a, lo, i - 1);
    quick(a, i + 1, hi);
}

int* sortScores(int* scores, int scoresSize, int* returnSize) {
    int* a = malloc(scoresSize * sizeof(int));
    memcpy(a, scores, scoresSize * sizeof(int));
    quick(a, 0, scoresSize - 1);
    *returnSize = scoresSize;
    return a;
}

