class Solution {
    private int[] a, buf;

    public int[] sortScores(int[] scores) {
        a = scores.clone();
        buf = new int[a.length];
        sort(0, a.length);
        return a;
    }

    private void sort(int lo, int hi) {
        if (hi - lo <= 1) return;
        int mid = (lo + hi) >>> 1;
        sort(lo, mid);
        sort(mid, hi);
        int i = lo, j = mid, k = lo;
        while (i < mid && j < hi) buf[k++] = a[i] <= a[j] ? a[i++] : a[j++];
        while (i < mid) buf[k++] = a[i++];
        while (j < hi) buf[k++] = a[j++];
        System.arraycopy(buf, lo, a, lo, hi - lo);
    }
}

