static void merge_sort(int* a, int* buf, int lo, int hi) {
    if (hi - lo <= 1) return;
    int mid = lo + (hi - lo) / 2;
    merge_sort(a, buf, lo, mid);
    merge_sort(a, buf, mid, hi);
    int i = lo, j = mid, k = lo;
    while (i < mid && j < hi) buf[k++] = a[i] <= a[j] ? a[i++] : a[j++];
    while (i < mid) buf[k++] = a[i++];
    while (j < hi) buf[k++] = a[j++];
    memcpy(a + lo, buf + lo, (hi - lo) * sizeof(int));
}

int* sortScores(int* scores, int scoresSize, int* returnSize) {
    int* a = malloc(scoresSize * sizeof(int));
    int* buf = malloc(scoresSize * sizeof(int));
    memcpy(a, scores, scoresSize * sizeof(int));
    merge_sort(a, buf, 0, scoresSize);
    free(buf);
    *returnSize = scoresSize;
    return a;
}
